'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var dlamch = require( '@stdlib/lapack/base/dlamch' );


// VARIABLES //

// Scale factor ratio below which equilibration is performed:
var THRESH = 0.1;

// Bounds on the largest matrix entry beyond which equilibration is performed:
var SMALL = dlamch( 'safe minimum' ) / dlamch( 'precision' );
var LARGE = 1.0 / SMALL;


// MAIN //

/**
* Equilibrates a real symmetric matrix `A` using the scaling factors in the vector `S`.
*
* @private
* @param {string} uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is referenced
* @param {NonNegativeInteger} N - order of the matrix `A`
* @param {Float64Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Float64Array} S - vector of scale factors
* @param {integer} strideS - stride length for `S`
* @param {NonNegativeInteger} offsetS - starting index for `S`
* @param {number} scond - ratio of the smallest scale factor to the largest scale factor
* @param {number} amax - absolute value of the largest matrix entry
* @returns {string} character flag indicating whether the matrix was equilibrated (`'Y'`) or not (`'N'`)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
*
* dlaqsy( 'upper', 3, A, 3, 1, 0, S, 1, 0, 0.0625, 9.0 );
* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
*/
function dlaqsy( uplo, N, A, strideA1, strideA2, offsetA, S, strideS, offsetS, scond, amax ) { // eslint-disable-line max-len, max-params
	var isrm;
	var sa0;
	var sa1;
	var is0;
	var is1;
	var ia;
	var cj;
	var i0;
	var i1;

	// Quick return if possible...
	if ( N <= 0 ) {
		return 'N';
	}
	// Return early if the matrix does not need to be equilibrated...
	if ( scond >= THRESH && amax >= SMALL && amax <= LARGE ) {
		return 'N';
	}
	isrm = isRowMajor( [ strideA1, strideA2 ] );
	if ( isrm ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		sa0 = strideA2; // stride for innermost loop
		sa1 = strideA1; // stride for outermost loop
	} else { // isColMajor
		// For column-major matrices, the first dimension has the fastest changing index...
		sa0 = strideA1; // stride for innermost loop
		sa1 = strideA2; // stride for outermost loop
	}
	// Row-major upper and column-major lower share the same traversal (and vice versa)...
	if (
		( !isrm && uplo === 'upper' ) ||
		( isrm && uplo === 'lower' )
	) {
		is1 = offsetS;
		for ( i1 = 0; i1 < N; i1++ ) {
			cj = S[ is1 ];
			ia = offsetA + ( sa1*i1 );
			is0 = offsetS;
			for ( i0 = 0; i0 <= i1; i0++ ) {
				A[ ia ] *= cj * S[ is0 ];
				ia += sa0;
				is0 += strideS;
			}
			is1 += strideS;
		}
		return 'Y';
	}
	// ( isrm && uplo === 'upper' ) || ( !isrm && uplo === 'lower' )
	is1 = offsetS;
	for ( i1 = 0; i1 < N; i1++ ) {
		cj = S[ is1 ];
		ia = offsetA + ( sa1*i1 ) + ( sa0*i1 );
		is0 = is1;
		for ( i0 = i1; i0 < N; i0++ ) {
			A[ ia ] *= cj * S[ is0 ];
			ia += sa0;
			is0 += strideS;
		}
		is1 += strideS;
	}
	return 'Y';
}


// EXPORTS //

module.exports = dlaqsy;
